INSERT INTO `projects` VALUES (1,'rogii','active',1,'目标: Kaggle \'Rogii Wellbore Geology Prediction\' 比赛冲牌 (RMSE 指标越低越好, 公榜噪声约±0.07, 最佳 LB 7.893)。\n正典: /Users/kanxiao/IdeaProjects/kaggletest/rogii/PROJECT_REPORT.md (泄漏机制/公榜噪声/全部实验证伪记录/方法论教训, 动手前必读)。\n外部资源: kaggle 比赛 rogii-wellbore-geology-prediction (查提交分: kaggle competitions submissions rogii-wellbore-geology-prediction)。\n工作区: rogii/ 为项目共享层 (Claude 因历史原因直接工作于此), rogii_codex/ 与 rogii_gemini/ 为对应 AI 的私有工作区。','2026-06-11 09:19:25'),(4,'arc_agi_2','active',0,'目标: Kaggle ARC Prize 2026 ARC-AGI-2 长期研究, 构建可验证的规则/搜索/LLM辅助solver体系(指标越高越好)。正典: /Users/kanxiao/IdeaProjects/kaggletest/arc_agi_2/PROJECT_REPORT.md。外部资源: kaggle competition arc-prize-2026-arc-agi-2。工作区: arc_agi_2/共享原始数据与正典, arc_agi_2_codex/arc_agi_2_gemini/arc_agi_2_claude为私有实验区, 原始数据不重复下载。','2026-06-11 01:47:48'),(5,'neurogolf','active',0,'目标: Kaggle NeuroGolf 2026 冲刺, 为400个ARC任务生成正确且尽量小的ONNX网络(指标越高越好)。正典: /Users/kanxiao/IdeaProjects/kaggletest/neurogolf/PROJECT_REPORT.md。外部资源: kaggle competition neurogolf-2026。工作区: neurogolf/共享原始数据与正典, neurogolf_codex/neurogolf_gemini/neurogolf_claude为私有实验区, 原始数据不重复下载。','2026-06-11 01:47:48');
